'use strict';
let YEAR=2026; const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const DEFAULTS={base:1365,daily:51,telephone:10,pension:7,social:5,rate:22.5};
const keyForYear=()=>`ameerFinancePWA${YEAR}_v1`; let KEY=keyForYear();
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const mvr=n=>'MVR '+new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
const num=v=>Number.isFinite(Number(v))?Number(v):0; const monthKey=i=>`${YEAR}-${String(i+1).padStart(2,'0')}`;
const defaultMonth=()=>({salary:{base:0,daily:0,telephone:0,pension:0,social:0,extraDeduction:0,otherAllowances:0,daysOverride:null,manual:false,active:false},budget:{rate:DEFAULTS.rate,actualExchange:''},expenses:[],otherIncome:[],allocations:[],mvrSavingsUsed:0});
function load(){let x;try{x=JSON.parse(localStorage.getItem(KEY))}catch(e){}if(!x||x.year!==YEAR)x={year:YEAR,defaults:{...DEFAULTS},months:Array.from({length:12},defaultMonth),leave:[],debts:[],savingsGoals:[]};if(!Array.isArray(x.months))x.months=Array.from({length:12},defaultMonth);while(x.months.length<12)x.months.push(defaultMonth());x.months=x.months.slice(0,12);if(!Array.isArray(x.leave))x.leave=[];if(!Array.isArray(x.debts))x.debts=[];try{const globalDebts=JSON.parse(localStorage.getItem('personalFinanceDebts_v1')||'null');if(Array.isArray(globalDebts))x.debts=globalDebts;else{const merged=[];for(let y=2026;y<=2036;y++){try{const oldYear=JSON.parse(localStorage.getItem(`ameerFinancePWA${y}_v1`)||'null');if(Array.isArray(oldYear?.debts))merged.push(...oldYear.debts)}catch(e){}}const unique=[...new Map(merged.map(d=>[d.id||`${d.person}-${d.date}-${d.amount}`,d])).values()];if(unique.length)x.debts=unique;localStorage.setItem('personalFinanceDebts_v1',JSON.stringify(x.debts))}}catch(e){}x.debts.forEach(d=>{if(!Array.isArray(d.payments))d.payments=[];if(d.legacyPaid===undefined)d.legacyPaid=Math.max(0,num(d.paidAmount)-d.payments.reduce((a,p)=>a+num(p.amount),0));if(d.completed===undefined)d.completed=false});if(!Array.isArray(x.savingsGoals))x.savingsGoals=[];if(!x.defaults)x.defaults={...DEFAULTS};x.months.forEach(m=>{if(!m.salary)m.salary=defaultMonth().salary;const q=m.salary;if(q.active===undefined){const matchesDefaults=['base','daily','telephone','pension','social'].every(k=>Math.abs(num(q[k])-num(x.defaults[k]??DEFAULTS[k]))<0.0001);if(YEAR>2026&&matchesDefaults){q.base=0;q.daily=0;q.telephone=0;q.pension=0;q.social=0;q.extraDeduction=0;q.otherAllowances=0;q.active=false}else q.active=[q.base,q.daily,q.telephone,q.pension,q.social].some(v=>num(v)!==0)}if(q.extraDeduction===undefined)q.extraDeduction=0;if(q.otherAllowances===undefined)q.otherAllowances=0;if(q.daysOverride===undefined)q.daysOverride=null;if(q.manual===undefined)q.manual=false;if(!m.budget)m.budget={rate:x.defaults.rate||DEFAULTS.rate,actualExchange:''};if(!Array.isArray(m.expenses))m.expenses=[];if(!Array.isArray(m.otherIncome))m.otherIncome=[];if(!Array.isArray(m.allocations))m.allocations=[];if(m.mvrSavingsUsed===undefined)m.mvrSavingsUsed=0});return x}
let db=load(), selected=10, activePage='dashboard',toastTimer;
if(!Array.isArray(db.debts))db.debts=[];if(!Array.isArray(db.savingsGoals))db.savingsGoals=[];
db.months.forEach(m=>{if(!Array.isArray(m.otherIncome))m.otherIncome=[];if(m.mvrSavingsUsed===undefined)m.mvrSavingsUsed=0;if(!Array.isArray(m.allocations))m.allocations=[];if(!m.salary)m.salary={...DEFAULTS,daysOverride:null,manual:false};if(m.salary.extraDeduction===undefined)m.salary.extraDeduction=0;if(m.salary.otherAllowances===undefined)m.salary.otherAllowances=0;if(m.mvrSavingsUsed===undefined)m.mvrSavingsUsed=0;});
function carryLedger(){try{return JSON.parse(localStorage.getItem('personalFinanceCarry_v1')||'{}')}catch(e){return {}}}
function openingBalances(){if(YEAR===2026)return {usd:0,mvr:0};const ledger=carryLedger();for(let y=YEAR-1;y>=2026;y--){if(ledger[String(y)])return ledger[String(y)]}return {usd:0,mvr:0}}
function persist(){localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem('personalFinanceDebts_v1',JSON.stringify(db.debts||[]));try{let usd=openingBalances().usd,mvrBal=openingBalances().mvr;for(let i=0;i<12;i++){const c=calc(i);usd+=c.saved;mvrBal+=c.mvrNetSaved;}const ledger=carryLedger();ledger[String(YEAR)]={usd,mvr:mvrBal};localStorage.setItem('personalFinanceCarry_v1',JSON.stringify(ledger))}catch(e){console.warn('Carry-forward update skipped',e)}}
function setYear(y){persist();YEAR=Number(y);KEY=keyForYear();db=load();if(!Array.isArray(db.savingsGoals))db.savingsGoals=[];db.months.forEach(m=>{if(!m.salary)m.salary=defaultMonth().salary;if(m.salary.active===undefined){const matchesDefaults=['base','daily','telephone','pension','social'].every(k=>Math.abs(num(m.salary[k])-num(db.defaults[k]??DEFAULTS[k]))<0.0001);if(YEAR>2026&&matchesDefaults){m.salary.base=0;m.salary.daily=0;m.salary.telephone=0;m.salary.pension=0;m.salary.social=0;m.salary.extraDeduction=0;m.salary.otherAllowances=0;m.salary.active=false}else m.salary.active=[m.salary.base,m.salary.daily,m.salary.telephone,m.salary.pension,m.salary.social].some(v=>num(v)!==0)}if(m.salary.extraDeduction===undefined)m.salary.extraDeduction=0;if(m.salary.otherAllowances===undefined)m.salary.otherAllowances=0;if(m.mvrSavingsUsed===undefined)m.mvrSavingsUsed=0;if(!Array.isArray(m.allocations))m.allocations=[];if(!Array.isArray(m.otherIncome))m.otherIncome=[];if(!Array.isArray(m.expenses))m.expenses=[];if(!m.budget)m.budget={rate:db.defaults.rate||DEFAULTS.rate,actualExchange:''}});selected=0;document.getElementById('yearSelect').value=YEAR;document.querySelector('.brand small').textContent='PERSONAL FINANCE · '+YEAR;document.title='Personal Finance — '+YEAR;document.querySelector('meta[name=description]').content='Private personal finance planner for '+YEAR;document.querySelectorAll('[data-year-text]').forEach(e=>e.textContent=YEAR);populateMonths();document.getElementById('leaveStart').min=YEAR+'-01-01';document.getElementById('leaveStart').max=YEAR+'-12-31';document.getElementById('leaveEnd').min=YEAR+'-01-01';document.getElementById('leaveEnd').max=YEAR+'-12-31';setMonth(0);showToast('Switched to '+YEAR+' — separate year records loaded')}

function current(){return db.months[selected]}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function validISODate(s){if(typeof s!=='string'||!/^\d{4}-\d\d-\d\d$/.test(s))return false;const d=new Date(s+'T12:00:00');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===s}
function dateInYear(s){return validISODate(s)&&s.startsWith(YEAR+'-')}
function inLeave(date){return db.leave.some(l=>date>=l.start&&date<=l.end)}
function workingDates(monthIndex){const last=new Date(YEAR,monthIndex+1,0).getDate(),arr=[];for(let d=1;d<=last;d++){const date=new Date(YEAR,monthIndex,d),day=date.getDay(),iso=`${YEAR}-${String(monthIndex+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;if([0,4,5,6].includes(day)&&!inLeave(iso))arr.push(iso)}return arr}
function autoPaidDays(i){const start=`${YEAR}-${String(i+1).padStart(2,'0')}-01`,end=`${YEAR}-${String(i+1).padStart(2,'0')}-${String(new Date(YEAR,i+1,0).getDate()).padStart(2,'0')}`;const hasLeave=db.leave.some(l=>l.start<=end&&l.end>=start);return hasLeave?workingDates(i).length:18.5}
function paidDays(i){const s=db.months[i].salary;return s.manual?Math.max(0,num(s.daysOverride)):autoPaidDays(i)}
function toUsd(amount,currency,rate){return currency==='USD'?num(amount):num(amount)/(num(rate)>0?num(rate):DEFAULTS.rate)}
function monthDebtPayments(i){const prefix=`${YEAR}-${String(i+1).padStart(2,'0')}`;return (db.debts||[]).flatMap(d=>(d.payments||[]).filter(p=>(p.date||'').startsWith(prefix)).map(p=>({...p,debtType:d.type,person:d.person,currency:d.currency,debtId:d.id})));}
function calc(i){const m=db.months[i],s=m.salary,b=m.budget,days=paidDays(i),pension=s.active?num(s.base)*num(s.pension)/100:0,otherAllowances=num(s.otherAllowances),calculatedGross=num(s.base)+num(s.daily)*days+num(s.telephone)+otherAllowances,gross=s.active?calculatedGross:0,extraDeduction=num(s.extraDeduction),net=s.active?gross-pension-num(s.social)-extraDeduction:0;
 const usdExpenses=m.expenses.filter(e=>e.currency==='USD').reduce((a,e)=>a+num(e.amount),0),mvrExpenses=m.expenses.filter(e=>e.currency==='MVR').reduce((a,e)=>a+num(e.amount),0),payments=monthDebtPayments(i);
 const usdDebtOut=payments.filter(p=>p.debtType==='payable'&&p.currency==='USD').reduce((a,p)=>a+num(p.amount),0),usdDebtIn=payments.filter(p=>p.debtType==='receivable'&&p.currency==='USD').reduce((a,p)=>a+num(p.amount),0),mvrDebtOut=payments.filter(p=>p.debtType==='payable'&&p.currency==='MVR').reduce((a,p)=>a+num(p.amount),0),mvrDebtIn=payments.filter(p=>p.debtType==='receivable'&&p.currency==='MVR').reduce((a,p)=>a+num(p.amount),0);
 const mvrIncome=(m.otherIncome||[]).filter(e=>e.currency==='MVR'),mvrIncomeCover=mvrIncome.reduce((a,e)=>a+Math.min(num(e.amount),Math.max(0,num(e.coverMvr))),0),mvrIncomeSaved=mvrIncome.reduce((a,e)=>a+Math.max(0,num(e.amount)-Math.min(num(e.amount),Math.max(0,num(e.coverMvr)))),0);
 const mvrDebtCover=payments.filter(p=>p.debtType==='receivable'&&p.currency==='MVR').reduce((a,p)=>a+Math.min(num(p.amount),num(p.coverMvr)),0),mvrDebtSaved=mvrDebtIn-mvrDebtCover;
 const rate=num(b.rate)>0?num(b.rate):DEFAULTS.rate,mvrCoverTotal=mvrIncomeCover+mvrDebtCover,mvrSavingsUsed=Math.max(0,num(m.mvrSavingsUsed)),mvrRemaining=Math.max(0,mvrExpenses+mvrDebtOut-mvrCoverTotal-mvrSavingsUsed),exchangeNeeded=mvrRemaining/rate;
 const actualUsd=num(b.actualExchange)>0?num(b.actualExchange):exchangeNeeded,usdOtherIncome=(m.otherIncome||[]).filter(e=>e.currency==='USD').reduce((a,e)=>a+num(e.amount),0),usdIncome=usdOtherIncome+usdDebtIn,usdExpenseTotal=usdExpenses+usdDebtOut,expenses=usdExpenseTotal+actualUsd,totalIncome=net+usdIncome,saved=totalIncome-expenses;
 const mvrNetSaved=mvrIncomeSaved+mvrDebtSaved-mvrSavingsUsed;
 return {days,pension,extraDeduction,otherAllowances,gross,net,usd:usdExpenses,mvr:mvrExpenses,usdDebtOut,usdDebtIn,mvrDebtOut,mvrDebtIn,mvrIncomeTotal:mvrIncome.reduce((a,e)=>a+num(e.amount),0)+mvrDebtIn,mvrIncomeCover,mvrIncomeSaved,mvrDebtCover,mvrDebtSaved,mvrCovered:mvrCoverTotal,mvrSaved:mvrIncomeSaved+mvrDebtSaved,mvrSavingsUsed,mvrRemaining,mvrUsd:actualUsd,exchangeNeeded,expenses,otherIncomeUsd:usdIncome,totalIncome,saved,mvrNetSaved,usdExpenses:usdExpenseTotal,mvrTotalExpenses:mvrExpenses+mvrDebtOut};}

function totalThrough(i){let n=0;for(let j=0;j<=i;j++)n+=calc(j).saved;return n}
function all(){return db.months.map((_,i)=>calc(i))}
function showToast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function populateMonths(){['dashMonth','salaryMonth','budgetMonth','reportMonth','debtMonth'].forEach(id=>{const el=document.getElementById(id);if(!el)return;el.innerHTML=MONTHS.map((m,i)=>`<option value="${i}">${m} ${YEAR}</option>`).join('');el.value=selected})}
function setMonth(i){selected=Math.max(0,Math.min(11,Number(i)));['dashMonth','salaryMonth','budgetMonth','debtMonth'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=selected});const reportMonth=document.getElementById('reportMonth');if(reportMonth)reportMonth.value=selected;document.getElementById('topMonth').textContent=MONTHS[selected]+' '+YEAR;renderAll()}
function go(page){activePage=page;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelectorAll('#mobileNav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function buildNav(){const names=[['dashboard','Overview'],['salary','Salary'],['leave','Leave'],['budget','Budget'],['savings','Savings'],['debts','Debts & loans'],['reports','Reports'],['settings','Settings']];document.getElementById('mobileNav').innerHTML=names.map(([p,n])=>`<button data-page="${p}" class="${p===activePage?'active':''}">${n}</button>`).join('');document.getElementById('mobileNav').addEventListener('click',e=>{const b=e.target.closest('button[data-page]');if(b)go(b.dataset.page)})}
function renderDashboard(){const c=calc(selected);document.getElementById('kpiSalary').textContent=money(c.net);document.getElementById('kpiDays').textContent=`${c.days} paid working days`;document.getElementById('kpiExpenses').textContent=money(c.expenses);document.getElementById('kpiExpenseMvr').textContent=`${mvr(c.mvr)} local expenses`;document.getElementById('kpiSavings').textContent=money(c.saved);document.getElementById('kpiBalance').textContent=money(openingBalances().usd+totalThrough(selected));const carry=document.getElementById('carriedForward');if(carry)carry.textContent=money(openingBalances().usd);const mvrCarry=document.getElementById('mvrCarriedForward');if(mvrCarry)mvrCarry.textContent=mvr(openingBalances().mvr);document.getElementById('snapshotMonth').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('snapGross').textContent=money(c.gross);document.getElementById('snapDeduct').textContent=money(current().salary.active?c.pension+num(current().salary.social)+c.extraDeduction:0);document.getElementById('snapUsd').textContent=money(c.usd);document.getElementById('snapMvr').textContent=money(c.mvrUsd);document.getElementById('snapExchangeNeeded').textContent=money(c.exchangeNeeded);document.getElementById('snapSaved').textContent=money(c.saved);document.getElementById('snapOtherIncome').textContent=money(c.otherIncomeUsd);renderCategories(c);drawChart()}
function renderCategories(c){const cats={};current().expenses.forEach(e=>{const v=toUsd(e.amount,e.currency,current().budget.rate);cats[e.category]=(cats[e.category]||0)+v});const entries=Object.entries(cats).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(x=>x[1]));document.getElementById('categoryList').innerHTML=entries.length?entries.map(([n,v])=>`<div class="category-row"><span>${escapeHtml(n)}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><b>${money(v)}</b></div>`).join(''):'<div class="empty-state">Add expenses to see your breakdown.</div>'}
function drawChart(){const canvas=document.getElementById('savingsChart');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.clientWidth||500,h=canvas.clientHeight||220,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const vals=all().map(x=>x.saved),max=Math.max(100,...vals.map(v=>Math.abs(v))),left=12,right=8,top=12,bottom=30,chartH=h-top-bottom,chartW=w-left-right;ctx.strokeStyle='#edf0f5';ctx.lineWidth=1;for(let k=0;k<4;k++){const y=top+k*chartH/3;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke()}const zero=top+chartH/2;ctx.strokeStyle='#d8dde7';ctx.beginPath();ctx.moveTo(left,zero);ctx.lineTo(w-right,zero);ctx.stroke();const slot=chartW/12,bw=Math.min(19,slot*.54);vals.forEach((v,i)=>{const bh=Math.abs(v)/max*(chartH*.43),x=left+i*slot+(slot-bw)/2,y=v>=0?zero-bh:zero;ctx.fillStyle=v>=0?'#5777d6':'#d98282';ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,bw,Math.max(2,bh),4);else ctx.rect(x,y,bw,Math.max(2,bh));ctx.fill();ctx.fillStyle='#8993a3';ctx.font='9px -apple-system, sans-serif';ctx.textAlign='center';ctx.fillText(MONTHS[i].slice(0,3),x+bw/2,h-9)})}
function renderSalary(){const s=current().salary,c=calc(selected);['basePay','dailyRate','telephone','pensionRate','socialFund','extraDeduction','otherAllowances'].forEach((id,k)=>document.getElementById(id).value=[s.base,s.daily,s.telephone,s.pension,s.social,num(s.extraDeduction),num(s.otherAllowances)][k]);document.getElementById('manualDays').checked=!!s.manual;document.getElementById('workedDays').value=s.manual?s.daysOverride:c.days;document.getElementById('workedDays').disabled=!s.manual;document.getElementById('workedDaysNote').textContent=s.manual?'Manual override is active.':(db.leave.some(l=>l.start<=`${YEAR}-${String(selected+1).padStart(2,'0')}-${String(new Date(YEAR,selected+1,0).getDate()).padStart(2,'0')}`&&l.end>=`${YEAR}-${String(selected+1).padStart(2,'0')}-01`)?'Auto-calculated: '+c.days+' actual Thu–Sun work days after excluding leave.':'Default paid working days: 18.5 (no leave in this month).');document.getElementById('slipMonth').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('slipBase').textContent=money(s.active?s.base:0);document.getElementById('slipAllowance').textContent=money(s.active?num(s.daily)*c.days:0);document.getElementById('slipPhone').textContent=money(s.active?s.telephone:0);document.getElementById('slipOtherAllowances').textContent=money(s.active?c.otherAllowances:0);document.getElementById('slipGross').textContent=money(c.gross);document.getElementById('slipPension').textContent='−'+money(s.active?c.pension:0);document.getElementById('slipSocial').textContent='−'+money(s.active?s.social:0);document.getElementById('slipExtra').textContent='−'+money(s.active?num(s.extraDeduction):0);document.getElementById('slipNet').textContent=money(c.net)}
function renderLeave(){const rows=[...db.leave].sort((a,b)=>a.start.localeCompare(b.start));document.getElementById('leaveCount').textContent=rows.length+' periods';document.getElementById('leaveRows').innerHTML=rows.length?rows.map(l=>{let excluded=0;for(let d=new Date(l.start+'T12:00:00');d<=new Date(l.end+'T12:00:00');d.setDate(d.getDate()+1))if([0,4,5,6].includes(d.getDay()))excluded++;return `<tr><td><b>${escapeHtml(l.label||'Annual leave')}</b></td><td>${l.start}</td><td>${l.end}</td><td>${excluded}</td><td><button class="table-action" data-delete-leave="${l.id}">Remove</button></td></tr>`}).join(''):'<tr><td colspan="5" class="empty-state">No leave periods added yet.</td></tr>';document.getElementById('monthDaysGrid').innerHTML=MONTHS.map((m,i)=>`<div class="month-day-card"><span>${m}</span><b>${paidDays(i)}</b><small>paid working days</small></div>`).join('')}
function currentMonthExpenses(i){return db.months[i]?.expenses||[]}
function renderBudget(){const m=current(),c=calc(selected);document.getElementById('exchangeRate').value=m.budget.rate;document.getElementById('actualExchange').value=m.budget.actualExchange;['summarySalary','summaryUsdIncome','summaryMvrIncome','summaryMvrIncomeCover','summaryMvrSavingsUsed','summaryUsdExpenses','summaryUsdDebtExpenses','summaryMvrExpenses','summaryMvrDebtExpenses','summaryTotalExpenses','summaryUsdSavings','summaryMvrSavings','summaryExchange'].forEach((id,k)=>{const v=[c.net,c.otherIncomeUsd-c.usdDebtIn+c.usdDebtIn,c.mvrIncomeTotal,c.mvrIncomeCover+c.mvrDebtCover,c.mvrSavingsUsed,c.usd,c.usdDebtOut,c.mvr,c.mvrDebtOut,c.expenses,c.saved,c.mvrNetSaved,c.exchangeNeeded][k];const el=document.getElementById(id);if(el)el.textContent=k===2||k===3||k===4||k===7||k===8||k===11?mvr(v):money(v)});renderDebtTransactions();document.getElementById('expenseTableSubtitle').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('expenseCount').textContent=m.expenses.length+' entries';document.getElementById('expenseDate').value=`${monthKey(selected)}-${String(new Date().getFullYear()===YEAR&&new Date().getMonth()===selected?new Date().getDate():1).padStart(2,'0')}`;document.getElementById('expenseRows').innerHTML=m.expenses.length?[...m.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>{const equiv=e.currency==='USD'?num(e.amount):num(e.amount)/num(m.budget.rate);return `<tr><td>${e.date}</td><td><b>${escapeHtml(e.description)}</b></td><td>${escapeHtml(e.category)}</td><td>${e.currency==='USD'?money(e.amount):mvr(e.amount)}</td><td>${money(equiv)}</td><td><button class="table-action" data-edit-expense="${e.id}">Edit</button> <button class="table-action" data-delete-expense="${e.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty-state">No expenses recorded for this month.</td></tr>'}
function mvrOpeningBalance(){return openingBalances().mvr}
function mvrBalanceThrough(i){let v=mvrOpeningBalance();for(let j=0;j<=i;j++)v+=calc(j).mvrNetSaved;return v}
function renderSavings(){const cs=all();let balance=openingBalances().usd,mvrBalance=mvrOpeningBalance();document.getElementById('savingsRows').innerHTML=cs.map((c,i)=>{balance+=c.saved;return `<tr><td><b>${MONTHS[i]}</b></td><td>${money(c.net+c.otherIncomeUsd)}</td><td>${money(c.expenses)}</td><td style="color:${c.saved>=0?'#13845b':'#bd5555'}"><b>${money(c.saved)}</b></td><td><b>${money(balance)}</b></td></tr>`}).join('');document.getElementById('mvrSavingsRows').innerHTML=cs.map((c,i)=>{const income=(db.months[i].otherIncome||[]).filter(x=>x.currency==='MVR').reduce((sum,x)=>sum+num(x.amount),0)+c.mvrDebtIn;mvrBalance+=c.mvrNetSaved;return `<tr><td><b>${MONTHS[i]}</b></td><td>${mvr(income)}</td><td>${mvr(c.mvrCovered+c.mvrSavingsUsed)}</td><td><b>${mvr(c.mvrNetSaved)}</b></td><td><b>${mvr(mvrBalance)}</b></td></tr>`}).join('');document.getElementById('mvrSavedMonth').textContent=mvr(calculateMvrPositive(selected));document.getElementById('mvrSavedBalance').textContent=mvr(mvrBalanceThrough(selected));const total=cs.reduce((a,c)=>a+c.saved,0);document.getElementById('annualSaved').textContent=money(total);document.getElementById('currentBalance').textContent=money(openingBalances().usd+totalThrough(selected));document.getElementById('averageSaved').textContent=money(total/12);renderSavingsGoals()}
function calculateMvrPositive(i){const c=calc(i);return c.mvrNetSaved}
function renderDebtTransactions(){const rows=monthDebtPayments(selected),body=document.getElementById('debtTransactionRows');if(!body)return;document.getElementById('debtTxnCount').textContent=rows.length+' transactions';body.innerHTML=rows.length?rows.map(p=>`<tr><td>${p.date}</td><td>${p.debtType==='payable'?'Debt repayment':'Collection'}</td><td><b>${escapeHtml(p.person)}</b></td><td>${p.currency==='USD'?money(p.amount):mvr(p.amount)}</td><td>${p.currency==='MVR'&&p.debtType==='receivable'?mvr(p.coverMvr):'—'}</td><td>${p.currency==='MVR'&&p.debtType==='receivable'?mvr(num(p.amount)-num(p.coverMvr)):'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">No debt transactions recorded for this month.</td></tr>'}


function renderIncome(){const m=current(),rate=m.budget.rate,rows=m.otherIncome||[];document.getElementById('incomeDate').value=`${monthKey(selected)}-${String(new Date().getFullYear()===YEAR&&new Date().getMonth()===selected?new Date().getDate():1).padStart(2,'0')}`;document.getElementById('incomeRows').innerHTML=rows.length?[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>{const covered=x.currency==='MVR'?Math.min(num(x.amount),Math.max(0,num(x.coverMvr))):0,saved=x.currency==='MVR'?Math.max(0,num(x.amount)-covered):0;return `<tr><td>${x.date}</td><td><b>${escapeHtml(x.description)}</b></td><td>${x.currency==='USD'?money(x.amount):mvr(x.amount)}</td><td>${x.currency==='USD'?money(x.amount):'—'}</td><td>${x.currency==='MVR'?mvr(covered):'—'}</td><td>${x.currency==='MVR'?mvr(saved):'—'}</td><td><button class="table-action" data-delete-income="${x.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="7" class="empty-state">No other income recorded for this month.</td></tr>'}
function addIncome(){const description=document.getElementById('incomeDescription').value.trim(),amount=num(document.getElementById('incomeAmount').value),currency=document.getElementById('incomeCurrency').value,date=document.getElementById('incomeDate').value,err=document.getElementById('incomeError');err.textContent='';if(!description||amount<=0){err.textContent='Enter a source and an amount greater than zero.';return}if(!dateInYear(date)||Number(date.slice(5,7))!==selected+1){err.textContent='Choose a date in the selected month.';return}const coverMvr=currency==='MVR'?num(document.getElementById('incomeCoverMvr').value):0;if(coverMvr<0||coverMvr>amount){err.textContent='MVR used for expenses cannot exceed the MVR income amount.';return}const mvrExpenses=calc(selected).mvrTotalExpenses,alreadyCovered=calc(selected).mvrCovered+num(current().mvrSavingsUsed);if(coverMvr+alreadyCovered>mvrExpenses){err.textContent=`You can allocate up to ${mvr(mvrExpenses-alreadyCovered)} more, based on this month’s MVR expenses.`;return}current().otherIncome.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),description,amount,currency,date,coverMvr});persist();document.getElementById('incomeDescription').value='';document.getElementById('incomeAmount').value='';document.getElementById('incomeCoverMvr').value='0';renderAll();showToast(currency==='MVR'?(coverMvr>0?'MVR income allocated; remainder saved in MVR':'All MVR income saved'):'Other income added')}

function goalProgress(g,monthIndex=selected){if(g.type==='monthly')return num(g.contributions?.[monthKey(monthIndex)]);const startYear=Number(g.startYear||YEAR),startMonth=Number(g.startMonth||0),start=startYear*12+startMonth,end=start+Math.max(1,Number(g.months)||12)-1,at=YEAR*12+monthIndex;if(at<start)return 0;return Object.entries(g.contributions||{}).reduce((sum,[key,value])=>{const [yy,mm]=key.split('-').map(Number),n=yy*12+(mm-1);return n>=start&&n<=Math.min(end,at)?sum+num(value):sum},0);}
function goalStatus(g,progress){if(progress>=num(g.target))return 'Achieved';if(g.targetDate){const t=new Date(g.targetDate+'T23:59:59');if(t<new Date())return 'Past target date'}return 'In progress'}
function renderSavingsGoals(){const rows=document.getElementById('savingsGoalRows');if(!rows)return;const goals=db.savingsGoals||[];document.getElementById('goalMonthLabel').textContent=MONTHS[selected]+' '+YEAR;rows.innerHTML=goals.length?goals.map(g=>{const progress=goalProgress(g),target=num(g.target),pct=target>0?Math.min(100,progress/target*100):0,status=goalStatus(g,progress),currency=g.currency||'USD',fmt=currency==='USD'?money:mvr,period=g.type==='within'?`Within ${g.months||1} month(s)`:g.type==='yearly'?'Yearly':'Monthly';return `<div class="goal-card"><div class="goal-top"><div><b>${escapeHtml(g.name)}</b><small>${currency} · ${period}</small></div><span class="goal-status ${status==='Achieved'?'achieved':''}">${status}</span></div><div class="goal-progress-track"><div class="goal-progress-fill" style="width:${pct}%"></div></div><div class="goal-bottom"><b>${fmt(progress)} <span>of ${fmt(target)}</span></b><span>${pct.toFixed(0)}%</span></div><div class="goal-meta">Target date: ${g.targetDate||'Not set'}</div><div class="goal-actions"><button class="table-action" data-goal-contribute="${g.id}">Record contribution</button><button class="table-action" data-goal-delete="${g.id}">Delete goal</button></div></div>`}).join(''):'<div class="empty-state">Create a savings goal to start tracking progress.</div>'}
function addSavingsGoal(){const name=document.getElementById('goalName').value.trim(),type=document.getElementById('goalType').value,target=num(document.getElementById('goalTarget').value),currency=document.getElementById('goalCurrency').value,months=num(document.getElementById('goalMonths').value),targetDate=document.getElementById('goalTargetDate').value,err=document.getElementById('goalError');err.textContent='';if(!name||target<=0){err.textContent='Enter a goal name and a target amount greater than zero.';return}const now=new Date(YEAR,selected,1);if(type==='within')now.setMonth(now.getMonth()+months);else if(type==='yearly')now.setMonth(now.getMonth()+12);const computed=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(new Date(now.getFullYear(),now.getMonth()+1,0).getDate()).padStart(2,'0')}`;db.savingsGoals.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name,type,target,currency,months:type==='within'?months:12,targetDate:targetDate||computed,startMonth:selected,startYear:YEAR,contributions:{}});persist();['goalName','goalTarget','goalTargetDate'].forEach(id=>document.getElementById(id).value='');renderSavingsGoals();showToast('Savings goal created')}
function recordGoalContribution(id){const g=db.savingsGoals.find(x=>x.id===id);if(!g)return;const fmt=g.currency==='MVR'?mvr:money,currentAmount=num(g.contributions?.[monthKey(selected)]),answer=prompt(`How much have you contributed to “${g.name}” in ${MONTHS[selected]}? (${g.currency||'USD'})`,String(currentAmount||''));if(answer===null)return;const amount=num(answer);if(amount<0){showToast('Enter zero or a positive amount');return}const available=g.currency==='MVR'?mvrBalanceThrough(selected):openingBalances().usd+totalThrough(selected);if(amount>available){showToast(`Contribution exceeds available ${g.currency||'USD'} savings`);return}if(!g.contributions)g.contributions={};g.contributions[monthKey(selected)]=amount;persist();renderSavingsGoals();showToast('Goal contribution saved')}

let debtView='active';
function debtCutoff(){return `${YEAR}-${String(selected+1).padStart(2,'0')}-${String(new Date(YEAR,selected+1,0).getDate()).padStart(2,'0')}`}
function paymentSumThrough(d,cutoff){const payments=Array.isArray(d.payments)?d.payments:[],recorded=payments.reduce((a,p)=>a+num(p.amount),0),legacy=Math.max(0,num(d.paidAmount)-recorded);return payments.filter(p=>(p.date||'')<=cutoff).reduce((a,p)=>a+num(p.amount),0)+((d.date||'')<=cutoff?legacy:0)}
function debtBalanceThrough(d,cutoff){if((d.date||'')>cutoff)return 0;return Math.max(0,num(d.amount)-paymentSumThrough(d,cutoff))}
function syncDebtPaid(d){const sum=(Array.isArray(d.payments)?d.payments:[]).reduce((a,p)=>a+num(p.amount),0);if(d.legacyPaid===undefined)d.legacyPaid=0;d.paidAmount=sum+num(d.legacyPaid);if(d.completed&&debtBalanceThrough(d,'9999-12-31')>0.005){d.completed=false;delete d.completedDate}}
function renderDebts(){const allRows=db.debts||[],cutoff=debtCutoff(),visible=allRows.filter(d=>(d.date||'')<=cutoff),active=allRows.filter(d=>!d.completed&&visible.includes(d)),completed=allRows.filter(d=>d.completed),rows=debtView==='completed'?completed:active;const sum=(type,currency)=>visible.filter(x=>x.type===type&&!x.completed&&x.currency===currency).reduce((a,x)=>a+debtBalanceThrough(x,cutoff),0);document.getElementById('debtOwedUsd').textContent=money(sum('payable','USD'));document.getElementById('debtOwedMvr').textContent=mvr(sum('payable','MVR'));document.getElementById('debtReceivableUsd').textContent=money(sum('receivable','USD'));document.getElementById('debtReceivableMvr').textContent=mvr(sum('receivable','MVR'));document.getElementById('debtCount').textContent=rows.length+' records';document.getElementById('completedDebtCount').textContent=completed.length;document.getElementById('debtMonthSubtitle').textContent=`Balances through ${cutoff}. Future-dated payments are excluded from this view.`;document.querySelectorAll('[data-debt-view]').forEach(b=>b.classList.toggle('active',b.dataset.debtView===debtView));document.getElementById('debtRows').innerHTML=rows.length?rows.map(x=>{const paid=paymentSumThrough(x,cutoff),balance=debtBalanceThrough(x,cutoff),fullyPaid=balance<0.005;return `<tr><td>${x.type==='payable'?'I owe':'Owed to me'}</td><td><b>${escapeHtml(x.person)}</b></td><td>${x.currency==='USD'?money(x.amount):mvr(x.amount)}</td><td>${x.currency==='USD'?money(paid):mvr(paid)}</td><td><b>${x.currency==='USD'?money(balance):mvr(balance)}</b></td><td>${escapeHtml(x.dueDate||'—')}</td><td>${escapeHtml(x.notes||'—')}</td><td class="debt-actions">${debtView==='active'?`<button class="table-action" data-debt-payment="${x.id}">Record payment</button> <button class="table-action" data-edit-debt="${x.id}">Edit</button> ${fullyPaid?`<button class="table-action" data-complete-debt="${x.id}">Mark completed</button>`:''}`:`<button class="table-action" data-edit-debt="${x.id}">Edit</button> <button class="table-action" data-reopen-debt="${x.id}">Move to active</button>`} <button class="table-action" data-delete-debt="${x.id}">Delete</button></td></tr>`}).join(''):`<tr><td colspan="8" class="empty-state">${debtView==='completed'?'No completed debts or loans yet.':'No active debts or loans recorded for this month.'}</td></tr>`;
 const history=allRows.flatMap(d=>(d.payments||[]).filter(p=>(p.date||'')<=cutoff).map(p=>({...p,debtId:d.id,person:d.person,type:d.type,currency:d.currency}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));document.getElementById('debtHistoryCount').textContent=history.length+' payments';document.getElementById('debtHistoryRows').innerHTML=history.length?history.map(p=>`<tr><td>${escapeHtml(p.date||'—')}</td><td><b>${escapeHtml(p.person)}</b></td><td>${p.type==='payable'?'Repayment':'Collection'}</td><td>${p.currency==='USD'?money(p.amount):mvr(p.amount)}</td><td>${p.currency==='MVR'&&p.type==='receivable'?mvr(p.coverMvr):'—'}</td><td><button class="table-action" data-edit-payment="${p.debtId}" data-payment-id="${p.id}">Edit</button> <button class="table-action" data-delete-payment="${p.debtId}" data-payment-id="${p.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">No payment history recorded yet.</td></tr>'}
function addDebt(){const type=document.getElementById('debtType').value,person=document.getElementById('debtPerson').value.trim(),amount=num(document.getElementById('debtAmount').value),currency=document.getElementById('debtCurrency').value,date=document.getElementById('debtDate').value||`${monthKey(selected)}-01`,dueDate=document.getElementById('debtDueDate').value,notes=document.getElementById('debtNotes').value.trim(),err=document.getElementById('debtError');err.textContent='';if(!person||amount<=0){err.textContent='Enter a person and an amount greater than zero.';return}if(!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036){err.textContent='Enter a valid date between 2026 and 2036.';return}db.debts.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),type,person,amount,paidAmount:0,currency,date,dueDate,notes,payments:[],completed:false});persist();['debtPerson','debtAmount','debtDate','debtDueDate','debtNotes'].forEach(id=>document.getElementById(id).value='');renderAll();showToast('Debt record added')}
function editDebt(id){const d=db.debts.find(x=>x.id===id);if(!d)return;const person=prompt('Person / lender / borrower',d.person);if(person===null)return;const type=prompt('Record type: payable (I owe) or receivable (owed to me)',d.type);if(type===null)return;const amount=prompt('Original amount',String(d.amount));if(amount===null)return;const currency=prompt('Currency: USD or MVR',d.currency);if(currency===null)return;const date=prompt('Record date (YYYY-MM-DD)',d.date||`${monthKey(selected)}-01`);if(date===null)return;const due=prompt('Due date (YYYY-MM-DD, blank for none)',d.dueDate||'');if(due===null)return;const notes=prompt('Notes',d.notes||'');if(notes===null)return;const n=num(amount),cur=currency.trim().toUpperCase(),validDate=validISODate(date)&&Number(date.slice(0,4))>=2026&&Number(date.slice(0,4))<=2036&&(d.payments||[]).every(p=>(p.date||date)>=date);if(!person.trim()||n<=0||n<paymentSumThrough(d,'9999-12-31')||!['payable','receivable'].includes(type.trim())||!['USD','MVR'].includes(cur)||!validDate){showToast('Invalid debt details. Check type, name, amount, currency and date.');return}Object.assign(d,{person:person.trim(),type:type.trim(),amount:n,currency:cur,date,dueDate:due.trim(),notes:notes.trim()});syncDebtPaid(d);persist();renderAll();showToast('Debt record updated')}
function recordDebtPayment(id){const d=db.debts.find(x=>x.id===id);if(!d)return;const outstanding=debtBalanceThrough(d,'9999-12-31');const answer=prompt(`Enter ${d.type==='payable'?'repayment':'collection'} amount (${d.currency}). Outstanding: ${d.currency==='USD'?money(outstanding):mvr(outstanding)}`);if(answer===null)return;const amount=num(answer);if(amount<=0||amount>outstanding){showToast('Enter a valid amount up to the outstanding balance');return}const defaultDate=`${monthKey(selected)}-${String(Math.min(new Date().getDate(),new Date(YEAR,selected+1,0).getDate())).padStart(2,'0')}`,date=prompt('Transaction date (YYYY-MM-DD)',defaultDate);if(!date||!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036||date<(d.date||'0000-01-01')){showToast('Enter a valid transaction date between 2026 and 2036');return}let coverMvr=0;if(d.type==='receivable'&&d.currency==='MVR'){const mi=Number(date.slice(5,7))-1;if(Number(date.slice(0,4))===YEAR&&mi>=0&&mi<12){const c=calc(mi),remaining=Math.max(0,c.mvrTotalExpenses-c.mvrCovered-num(db.months[mi].mvrSavingsUsed));const cover=prompt(`How much of this collection should cover MVR expenses? Enter 0 to save all. Maximum: ${mvr(Math.min(amount,remaining))}`,'0');if(cover===null)return;coverMvr=num(cover);if(coverMvr<0||coverMvr>amount||coverMvr>remaining){showToast('Invalid MVR expense allocation');return}}}if(!Array.isArray(d.payments))d.payments=[];d.payments.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),date,amount,coverMvr});syncDebtPaid(d);persist();renderAll();showToast('Payment recorded')}
function editDebtPayment(debtId,paymentId){const d=db.debts.find(x=>x.id===debtId),p=d?.payments?.find(x=>x.id===paymentId);if(!p)return;const date=prompt('Payment date (YYYY-MM-DD)',p.date);if(date===null)return;const amount=prompt('Payment amount',String(p.amount));if(amount===null)return;const cover=prompt('MVR amount used for expenses (0 if not applicable)',String(num(p.coverMvr)));if(cover===null)return;const n=num(amount),c=num(cover),maxAllowed=debtBalanceThrough(d,'9999-12-31')+num(p.amount);if(!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036||date<(d.date||'0000-01-01')||n<=0||n>maxAllowed||c<0||c>n){showToast('Invalid payment details');return}p.date=date;p.amount=n;p.coverMvr=c;syncDebtPaid(d);persist();renderAll();showToast('Payment updated')}
function deleteDebtPayment(debtId,paymentId){const d=db.debts.find(x=>x.id===debtId);if(!d||!confirm('Delete this payment transaction? The outstanding balance will be recalculated.'))return;d.payments=(d.payments||[]).filter(p=>p.id!==paymentId);syncDebtPaid(d);persist();renderAll();showToast('Payment deleted and balance recalculated')}

function useMvrSavings(){const amount=num(document.getElementById('mvrSavingsUseAmount').value),errMax=mvrBalanceThrough(selected)-calc(selected).mvrNetSaved;if(amount<=0){showToast('Enter an amount greater than zero');return}const available=Math.max(0,mvrOpeningBalance()+all().slice(0,selected).reduce((a,c)=>a+c.mvrNetSaved,0));if(amount>available){showToast(`Available MVR savings: ${mvr(available)}`);return}const maxNeed=Math.max(0,calc(selected).mvrTotalExpenses-calc(selected).mvrCovered-num(current().mvrSavingsUsed));if(amount>maxNeed){showToast(`MVR expenses remaining after income cover: ${mvr(maxNeed)}`);return}current().mvrSavingsUsed=num(current().mvrSavingsUsed)+amount;persist();document.getElementById('mvrSavingsUseAmount').value='';renderAll();showToast('MVR savings applied to this month’s expenses')}
function renderReports(){const cs=all();let income=0,expenses=0,savings=0;cs.forEach((c,i)=>{if(i<=selected){const fx=num(db.months[i].budget.rate)||DEFAULTS.rate;income+=c.totalIncome+c.mvrIncomeTotal/fx;expenses+=c.expenses;savings+=c.saved+c.mvrNetSaved/fx}});document.getElementById('reportIncome').textContent=money(income);document.getElementById('reportExpenses').textContent=money(expenses);document.getElementById('reportRate').textContent=income?((savings/income)*100).toFixed(1)+'%':'0%';const rows=document.getElementById('reportRows');if(rows)rows.innerHTML=cs.map((c,i)=>`<tr><td><b>${MONTHS[i]}</b></td><td>${c.days}</td><td>${money(c.net)}</td><td>${money(c.usdExpenses)}</td><td>${mvr(c.mvrTotalExpenses)}</td><td>${money(c.saved+c.mvrNetSaved/(num(db.months[i].budget.rate)||DEFAULTS.rate))}</td></tr>`).join('');const sel=document.getElementById('reportMonth');if(sel)sel.value=String(selected)}

function renderSettings(){const d=db.defaults;['defaultBase','defaultDaily','defaultPhone','defaultPension','defaultSocial','defaultRate'].forEach((id,i)=>document.getElementById(id).value=[d.base,d.daily,d.telephone,d.pension,d.social,d.rate][i])}
function renderAll(){document.getElementById('topMonth').textContent=MONTHS[selected]+' '+YEAR;renderDashboard();renderSalary();renderLeave();renderBudget();renderIncome();renderSavings();renderDebts();renderReports();renderSettings()}
function saveSalary(){const s=current().salary;s.base=num(document.getElementById('basePay').value);s.daily=num(document.getElementById('dailyRate').value);s.telephone=num(document.getElementById('telephone').value);s.pension=num(document.getElementById('pensionRate').value);s.social=num(document.getElementById('socialFund').value);s.extraDeduction=num(document.getElementById('extraDeduction').value);s.otherAllowances=num(document.getElementById('otherAllowances').value);s.manual=document.getElementById('manualDays').checked;s.daysOverride=s.manual?num(document.getElementById('workedDays').value):null;s.active=true;delete s.pendingDefaults;persist();renderAll();showToast('Salary settings saved')}
function saveBudget(){const rate=num(document.getElementById('exchangeRate').value);if(rate<=0){showToast('Enter a valid exchange rate');return}current().budget.rate=rate;current().budget.actualExchange=document.getElementById('actualExchange').value;persist();renderAll();showToast('Exchange settings saved')}
function addLeave(){const start=document.getElementById('leaveStart').value,end=document.getElementById('leaveEnd').value,err=document.getElementById('leaveError');err.textContent='';if(!dateInYear(start)||!dateInYear(end)){err.textContent='Choose valid dates within '+YEAR+'.';return}if(end<start){err.textContent='The end date must be on or after the start date.';return}if(db.leave.some(l=>start<=l.end&&end>=l.start)){err.textContent='This period overlaps an existing leave period. Edit your dates to avoid overlap.';return}db.leave.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),start,end,label:document.getElementById('leaveLabel').value.trim()||'Annual leave'});persist();document.getElementById('leaveStart').value='';document.getElementById('leaveEnd').value='';document.getElementById('leaveLabel').value='';renderAll();showToast('Leave period added; working days recalculated')}
function addExpense(){const desc=document.getElementById('expenseDescription').value.trim(),amount=num(document.getElementById('expenseAmount').value),currency=document.getElementById('expenseCurrency').value,date=document.getElementById('expenseDate').value,err=document.getElementById('expenseError');err.textContent='';if(!desc||amount<=0){err.textContent='Enter a description and an amount greater than zero.';return}if(!dateInYear(date)||Number(date.slice(5,7))!==selected+1){err.textContent='Choose a date in the selected month of '+YEAR+'.';return}current().expenses.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),description:desc,category:document.getElementById('expenseCategory').value,amount,currency,date});persist();document.getElementById('expenseDescription').value='';document.getElementById('expenseAmount').value='';renderAll();showToast('Expense added')}
function exportFile(obj,name,type='application/json'){const blob=new Blob([type==='text/csv'?obj:JSON.stringify(obj,null,2)],{type:type==='text/csv'?'text/csv':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportCsv(){const rows=[['Month','Paid working days','Gross salary USD','Net salary USD','Other income USD','Total income USD','USD expenses','MVR expenses','MVR covered by MVR income','MVR saved','MVR expense USD equivalent','Total expenses USD','Savings USD','Running balance USD']];let balance=openingBalances().usd;all().forEach((c,i)=>{balance+=c.saved;rows.push([MONTHS[i],c.days,c.gross,c.net,c.otherIncomeUsd,c.totalIncome,c.usd,c.mvr,c.mvrCovered,c.mvrSaved,c.mvrUsd,c.expenses,c.saved,balance])});const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\\n');exportFile(csv,`personal-finance-${YEAR}-report.csv`,'text/csv')}
function wire(){document.getElementById('nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.goto)));['dashMonth','salaryMonth','budgetMonth','debtMonth'].forEach(id=>document.getElementById(id).addEventListener('change',e=>setMonth(e.target.value)));document.getElementById('topMonth').addEventListener('click',()=>go('dashboard'));document.getElementById('saveSalary').addEventListener('click',saveSalary);document.getElementById('resetSalary').addEventListener('click',()=>{if(!confirm('Load the saved default salary settings for this month? Press Save salary settings afterward to activate them.'))return;current().salary={...db.defaults,extraDeduction:0,otherAllowances:0,daysOverride:null,manual:false,active:false,pendingDefaults:true};persist();renderAll();showToast('Defaults loaded. Press Save salary settings to activate.')});document.getElementById('manualDays').addEventListener('change',e=>{document.getElementById('workedDays').disabled=!e.target.checked;if(!e.target.checked)document.getElementById('workedDays').value=autoPaidDays(selected)});document.getElementById('addLeave').addEventListener('click',addLeave);document.getElementById('leaveRows').addEventListener('click',e=>{const b=e.target.closest('[data-delete-leave]');if(b&&confirm('Remove this leave period?')){db.leave=db.leave.filter(l=>l.id!==b.dataset.deleteLeave);persist();renderAll();showToast('Leave period removed')}});document.getElementById('saveBudgetSettings').addEventListener('click',saveBudget);document.getElementById('addIncome').addEventListener('click',addIncome);document.getElementById('incomeCurrency').addEventListener('change',e=>{document.getElementById('incomeCoverField').hidden=e.target.value!=='MVR';document.getElementById('incomeCoverMvr').value='0'});document.getElementById('incomeRows').addEventListener('click',e=>{const b=e.target.closest('[data-delete-income]');if(b&&confirm('Delete this income entry?')){current().otherIncome=current().otherIncome.filter(x=>x.id!==b.dataset.deleteIncome);persist();renderAll();showToast('Income entry deleted')}});document.getElementById('addSavingsGoal').addEventListener('click',addSavingsGoal);document.getElementById('goalType').addEventListener('change',e=>{document.getElementById('goalMonthsField').hidden=e.target.value!=='within'});document.getElementById('useMvrSavings').addEventListener('click',useMvrSavings);document.getElementById('reportMonth').addEventListener('change',e=>setMonth(e.target.value));document.getElementById('savingsGoalRows').addEventListener('click',e=>{const c=e.target.closest('[data-goal-contribute]'),d=e.target.closest('[data-goal-delete]');if(c)recordGoalContribution(c.dataset.goalContribute);if(d&&confirm('Delete this savings goal?')){db.savingsGoals=db.savingsGoals.filter(g=>g.id!==d.dataset.goalDelete);persist();renderSavingsGoals();showToast('Savings goal deleted')}});document.getElementById('addDebt').addEventListener('click',addDebt);document.getElementById('debtRows').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.deleteDebt||b.dataset.debtPayment||b.dataset.editDebt||b.dataset.completeDebt||b.dataset.reopenDebt;if(b.dataset.deleteDebt){if(confirm('Delete this debt record and its payment history?')){db.debts=db.debts.filter(x=>x.id!==id);persist();renderAll();showToast('Debt record deleted')}}else if(b.dataset.debtPayment)recordDebtPayment(id);else if(b.dataset.editDebt)editDebt(id);else if(b.dataset.completeDebt){const d=db.debts.find(x=>x.id===id);if(d&&debtBalanceThrough(d,debtCutoff())<0.005&&confirm('Sign off this fully paid debt and move it to Completed for this month?')){d.completed=true;d.completedDate=debtCutoff();persist();renderAll();showToast('Moved to completed debts')}}else if(b.dataset.reopenDebt){const d=db.debts.find(x=>x.id===id);if(d){d.completed=false;delete d.completedDate;persist();renderAll();showToast('Moved back to active debts')}}});document.querySelectorAll('[data-debt-view]').forEach(b=>b.addEventListener('click',()=>{debtView=b.dataset.debtView;renderDebts()}));document.getElementById('debtHistoryRows').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const did=b.dataset.editPayment||b.dataset.deletePayment,pid=b.dataset.paymentId;if(b.dataset.editPayment)editDebtPayment(did,pid);if(b.dataset.deletePayment)deleteDebtPayment(did,pid)});document.getElementById('addExpense').addEventListener('click',addExpense);document.getElementById('expenseRows').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.deleteExpense||b.dataset.editExpense,item=current().expenses.find(x=>x.id===id);if(b.dataset.deleteExpense&&item&&confirm('Delete this expense?')){current().expenses=current().expenses.filter(x=>x.id!==id);persist();renderAll();showToast('Expense deleted')}else if(b.dataset.editExpense&&item){const description=prompt('Expense description',item.description);if(description===null)return;const category=prompt('Category',item.category);if(category===null)return;const amount=prompt('Amount',String(item.amount));if(amount===null)return;const currency=prompt('Currency (USD or MVR)',item.currency);if(currency===null)return;const date=prompt('Date (YYYY-MM-DD)',item.date);if(date===null)return;const n=num(amount),cur=currency.trim().toUpperCase();if(!description.trim()||n<=0||!['USD','MVR'].includes(cur)||!dateInYear(date)||Number(date.slice(5,7))!==selected+1){showToast('Invalid expense details. Check description, amount, currency and selected-month date.');return}Object.assign(item,{description:description.trim(),category:category.trim(),amount:n,currency:cur,date});persist();renderAll();showToast('Expense updated')}});document.getElementById('copyExpenses').addEventListener('click',()=>{let source=null,sourceYear=YEAR;if(selected>0)source=currentMonthExpenses(selected-1);else{sourceYear=YEAR-1;try{const prev=JSON.parse(localStorage.getItem(`ameerFinancePWA${sourceYear}_v1`)||'null');source=prev?.months?.[11]?.expenses||null}catch(e){source=null}}if(!source||!source.length){showToast('No previous-month expenses found to copy');return}if(current().expenses.length&&!confirm('This month already has expenses. Copy previous month entries and add them to the existing list?'))return;const lastDay=new Date(YEAR,selected+1,0).getDate();source.forEach(e=>{const day=Math.min(Number((e.date||'').slice(8,10))||1,lastDay),date=`${monthKey(selected)}-${String(day).padStart(2,'0')}`;current().expenses.push({...e,id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random(),date})});persist();renderAll();showToast(`${source.length} previous-month expenses copied`)});document.getElementById('saveDefaults').addEventListener('click',()=>{db.defaults={base:num(defaultBase.value),daily:num(defaultDaily.value),telephone:num(defaultPhone.value),pension:num(defaultPension.value),social:num(defaultSocial.value),rate:num(defaultRate.value)};persist();renderSettings();showToast('Defaults saved; existing months unchanged')});document.getElementById('exportBackup').addEventListener('click',()=>exportFile(db,`personal-finance-${YEAR}-backup.json`));document.getElementById('importBackup').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(x.year!==YEAR||!Array.isArray(x.months)||x.months.length!==12||!Array.isArray(x.leave)||!x.defaults)throw Error('This is not a valid Personal Finance backup for the selected year.');if(!confirm('Restore this backup? The selected year’s records will be replaced; existing debts from other years will be kept and matching debt records updated.'))return;const existingDebts=Array.isArray(db.debts)?db.debts:[];db=x;if(!Array.isArray(db.debts))db.debts=[];const debtMerge=new Map(existingDebts.map(d=>[d.id,d]));db.debts.forEach(d=>debtMerge.set(d.id,d));db.debts=Array.from(debtMerge.values());if(!Array.isArray(db.savingsGoals))db.savingsGoals=[];db.months.forEach(m=>{if(!Array.isArray(m.otherIncome))m.otherIncome=[];if(!Array.isArray(m.expenses))m.expenses=[];if(m.mvrSavingsUsed===undefined)m.mvrSavingsUsed=0;if(!Array.isArray(m.allocations))m.allocations=[];if(!m.salary)m.salary=defaultMonth().salary;if(m.salary.active===undefined){const matchesDefaults=['base','daily','telephone','pension','social'].every(k=>Math.abs(num(m.salary[k])-num(db.defaults[k]??DEFAULTS[k]))<0.0001);if(YEAR>2026&&matchesDefaults){m.salary.base=0;m.salary.daily=0;m.salary.telephone=0;m.salary.pension=0;m.salary.social=0;m.salary.extraDeduction=0;m.salary.otherAllowances=0;m.salary.active=false}else m.salary.active=[m.salary.base,m.salary.daily,m.salary.telephone,m.salary.pension,m.salary.social].some(v=>num(v)!==0)}if(m.salary.extraDeduction===undefined)m.salary.extraDeduction=0;if(m.salary.otherAllowances===undefined)m.salary.otherAllowances=0;if(!m.budget)m.budget={rate:db.defaults.rate||DEFAULTS.rate,actualExchange:''}});db.debts.forEach(d=>{if(!Array.isArray(d.payments))d.payments=[];if(d.legacyPaid===undefined)d.legacyPaid=Math.max(0,num(d.paidAmount)-d.payments.reduce((a,p)=>a+num(p.amount),0));if(d.completed===undefined)d.completed=false});persist();renderAll();showToast('Backup restored successfully')}catch(err){document.getElementById('backupMessage').textContent=err.message||'Could not read backup file.'}finally{e.target.value=''}});document.getElementById('clearData').addEventListener('click',()=>{if(!confirm('Permanently clear all finance data saved in this browser? Export a backup first.'))return;if(!confirm('Final confirmation: delete all salary, leave and expense records?'))return;db={year:YEAR,defaults:{...DEFAULTS},months:Array.from({length:12},defaultMonth),leave:[],debts:[],savingsGoals:[]};persist();renderAll();showToast('All app data cleared')});document.getElementById('downloadCsv').addEventListener('click',exportCsv);document.getElementById('yearSelect').addEventListener('change',e=>setYear(e.target.value));window.addEventListener('resize',()=>{if(activePage==='dashboard')drawChart()})}
populateMonths();buildNav();wire();document.getElementById('yearSelect').value=YEAR;setYearOnLabels();setMonth(new Date().getFullYear()===YEAR?new Date().getMonth():0);
function setYearOnLabels(){document.querySelectorAll('[data-year-text]').forEach(e=>e.textContent=YEAR);document.querySelector('.brand small').textContent='PERSONAL FINANCE · '+YEAR;document.title='Personal Finance — '+YEAR;document.getElementById('leaveStart').min=YEAR+'-01-01';document.getElementById('leaveStart').max=YEAR+'-12-31';document.getElementById('leaveEnd').min=YEAR+'-01-01';document.getElementById('leaveEnd').max=YEAR+'-12-31'}if('serviceWorker'in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
